import {stats} from './core.js?v=5';
export function equipItem(player,id,enabled=true,inCombat=false){const item=player.bag.find(i=>i.id===id);if(!item)return {ok:false,reason:'Item não encontrado.'};if(inCombat)return {ok:false,reason:'Saia de combate por10s para trocar equipamentos.'};if(enabled&&item.classId!==player.classId)return {ok:false,reason:'Item de outra classe.'};if(enabled&&player.level<item.level)return {ok:false,reason:'Requer nível'+item.level+'.'};if(enabled&&player.classId==='RUP'&&item.slot==='secondary')return {ok:false,reason:'Ruptor usa uma arma unificada.'};if(enabled)player.equipped[item.slot]=id;else if(player.equipped[item.slot]===id)player.equipped[item.slot]=null;player.hp=Math.min(player.hp,stats(player).hp);player.mp=Math.min(player.mp,stats(player).mp);return {ok:true};}
export function appearanceFor(player){const armor=player.bag.find(i=>i.id===player.equipped.armor),weapon=player.bag.find(i=>i.id===player.equipped.weapon);return {quality:armor?.quality||'D',enchant:weapon?.enchant||0,hasWeapon:!!weapon,hasSecondary:!!player.equipped.secondary,hasArmor:!!armor,hasHead:!!player.equipped.head,hasHands:!!player.equipped.hands,hasLegs:!!player.equipped.legs,hasBoots:!!player.equipped.boots};}
